import { readFile, readdir, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = fileURLToPath(new URL('../', import.meta.url));
const read = (file) => readFile(path.join(root, file), 'utf8');
const lock = JSON.parse(await read('package-lock.json'));
const fallback = {
  '@mirohq/miro-api@2.2.4': 'legal/miro-api-2.2.4-LICENSE.txt',
  'tr46@0.0.3': 'legal/tr46-LICENSE.txt',
};
const sections = [
  'THIRD-PARTY NOTICES',
  'Generated by npm run licenses from installed, locked production dependencies.\n'
    + 'These components retain their own licenses and copyrights.\n'
    + 'License sources and fallback provenance: legal/README.md in the source repository.\n'
    + 'Electron also distributes LICENSE.electron.txt and LICENSES.chromium.html; retain both.',
];
for (const [location, metadata] of Object.entries(lock.packages).sort(([a], [b]) => a.localeCompare(b))) {
  if (!location || (metadata.dev && location !== 'node_modules/electron')) continue;
  const pkg = JSON.parse(await read(`${location}/package.json`));
  if (pkg.version !== metadata.version) throw new Error(`Installed version differs from lock: ${location}`);
  const key = `${pkg.name}@${pkg.version}`;
  const files = (await readdir(path.join(root, location))).filter(
    (name) => /^(licen[sc]e|copying|notice)(\.|$)/i.test(name),
  ).sort();
  const licenses = files.filter((name) => /^(licen[sc]e|copying)(\.|$)/i.test(name));
  if (!licenses.length && !fallback[key]) throw new Error(`Missing license text: ${key}`);
  sections.push(`${'='.repeat(72)}\n${key}\nDeclared license: ${pkg.license ?? 'unspecified'}`);
  for (const file of files) sections.push(`${file}\n\n${(await read(`${location}/${file}`)).trim()}`);
  if (!licenses.length) sections.push(`Fallback: ${fallback[key]}\n\n${(await read(fallback[key])).trim()}`);
}
sections.push(`${'='.repeat(72)}\nUnicode mapping data\n\n${(await read('legal/UNICODE-LICENSE.txt')).trim()}`);
await writeFile(path.join(root, 'THIRD_PARTY_NOTICES.txt'), sections.join('\n\n') + '\n');
console.log('Generated THIRD_PARTY_NOTICES.txt');
